const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='delivery-manager-manager-v1';let config;try{config=JSON.parse(localStorage.getItem(key)||'null');}catch{}let draft,packet;try{draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+config?.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+config?.id)||'null');}catch{draft=[];}let draftKind=localStorage.getItem('dm-manager-kind-'+config?.id)||'single';let error='',sending=false,statuses=[],driverView=null;let sentExpanded=new Map();let selectedSent=new Set(),dismissedRecommendations=new Set(),groupPending=false;let drivers=savedManagerDrivers(localStorage);if(config)config=drivers.find(c=>c.id===config.id)||config;
const persist=()=>{localStorage.setItem('dm-manager-kind-'+config.id,draftKind);localStorage.setItem('dm-manager-draft-'+config.id,JSON.stringify(draft));packet?localStorage.setItem('dm-manager-outbox-'+config.id,JSON.stringify(packet)):localStorage.removeItem('dm-manager-outbox-'+config.id);};
function render(){document.querySelectorAll('details[data-sent-group]').forEach(d=>sentExpanded.set(d.dataset.sentGroup,d.open));$('#manager').innerHTML=`<header class="manager-brand"><img src="icon.svg" alt=""><div><h1>Mike’s Dispatch</h1><p>Add orders. Send them to your driver.</p></div></header>${drivers.length?`<section class="card manager-driver-choice"><label for="dispatch-driver">Send orders to</label><select id="dispatch-driver" ${sending||draft.length||packet?'disabled':''}><option value="">Choose a saved driver</option>${drivers.map(c=>`<option value="${esc(c.id)}" ${c.id===config?.id?'selected':''}>${esc(c.driverName||'Driver')} · ${c.mode==='test'?'Test':'Live'}</option>`).join('')}</select><p class="muted">Pair each phone once. Choose the driver here at the start of a shift. Finish the current addition before switching.</p>${scheduleHint()}${config?'<button id="rename-driver">Rename driver</button>':''}</section>`:''}${config?`<div class="${config.mode==='test'?'demo-banner':'hint'}"><strong>${config.mode==='test'?'TEST DISPATCH — fictional orders only':'LIVE DISPATCH — real driver records'}</strong></div><section class="card"><h2>Build an addition</h2><p>Every order sent together gets the same color on the driver’s phone. Order below is the requested stop order; due-soon scheduled orders can move first.</p>${draft.map((d,i)=>`<div class="manager-stop"><div><strong>${i+1}. ${esc(d.name||'Delivery')}</strong><p>${esc(d.address)}</p>${d.scheduledAt?'<span class="badge scheduled">Scheduled</span>':''}</div><div>${!packet?`<button data-edit="${i}">Edit</button><button data-up="${i}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" ${i===draft.length-1?'disabled':''}>↓</button><button data-remove="${i}">Remove</button>`:''}</div></div>`).join('')}${draft.length?`<div class="batch-route-actions"><button type="button" id="customize-draft-route" class="primary" ${sending||packet?'disabled':''}>Customize route</button><button type="button" id="view-draft-route">View route</button></div>`:''}<div class="actions"><button id="add" class="primary" ${packet||draft.length>=12?'disabled':''}>+ Add order</button></div><label for="send-kind">Send these orders as</label><select id="send-kind" ${packet?'disabled':''}><option value="single">${draft.length>1?'Separate single deliveries':'Single delivery'}</option><option value="batch">One batch</option></select><p class="muted">One send = one addition. Orders arrive ready for delivery. The driver chooses when to start the run. Unstarted single orders can be combined into a batch. Contact the driver for other corrections or cancellations.</p><button id="send" class="primary" ${sending||(!draft.length&&!packet)?'disabled':''}>${sending?'Sending…':packet?(packet.operation==='reorder'?'Retry route request':packet.operation==='group'?'Retry batch request':'Retry same addition'):'Send addition to '+esc(config.driverName||'driver')}</button>${packet?'<p class="hint">A send is awaiting confirmation. Retry uses the same ID to prevent duplicates; editing is locked until it is resolved.</p>':''}</section>${sentOrderView()}<section class="card"><div class="row"><h2>Recent sends</h2><button id="refresh">Refresh status</button></div><p class="muted">Received means saved on the driver’s phone. Queued means awaiting collection; it expires after 24 hours.</p>${statuses.map(x=>`<p>${new Date(x.created_at).toLocaleString()} · <strong>${esc(x.status)}</strong></p>`).join('')||'<p>No sends checked yet.</p>'}</section><button id="unpair">Pair another driver</button><p class="muted">Order details are encrypted on this device before upload. The server deletes the encrypted copy after receipt or expiry. This phone keeps unsent drafts locally. Keep the pairing code private.</p>`:`<section class="card"><h2>Connect to a driver</h2><p>On the driver’s app, open Settings → Mike’s dispatch. Create a test or live pairing and paste its private code here.</p><form id="pair-form"><label for="driver-name">Driver name</label><input id="driver-name" maxlength="40" required placeholder="Tony or Charlotte"><label for="pair-code">Pairing code</label><textarea id="pair-code" required autocomplete="off" autocapitalize="off" spellcheck="false"></textarea><button class="primary">Connect manager</button></form></section>`}<p class="error" role="alert">${esc(error)}</p>`;
 bindDriverChoice();bindSentOrders();bindManagerRoutes();if(!config){$('#pair-form').onsubmit=async e=>{e.preventDefault();try{const c=parsePairingCode($('#pair-code').value.trim());await dispatchCall('status',{},c.token);config=rememberManagerDriver(localStorage,c,$('#driver-name').value);drivers=savedManagerDrivers(localStorage);draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+c.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+c.id)||'null');draftKind=localStorage.getItem('dm-manager-kind-'+c.id)||'single';error='';render();}catch(e){error=e.message;render();}};return;}
 $('#send-kind').value=draftKind;$('#send-kind').onchange=()=>{draftKind=$('#send-kind').value;persist();};$('#add').onclick=()=>orderForm();$('#send').onclick=send;$('#refresh').onclick=refresh;$('#unpair').onclick=()=>{if(draft.length||packet)return fail('Finish or remove the current draft before changing pairing.');localStorage.removeItem(key);config=null;draft=[];packet=null;statuses=[];driverView=null;selectedSent.clear();groupPending=false;error='';render();};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>orderForm(Number(b.dataset.edit)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{draft.splice(Number(b.dataset.remove),1);persist();render();});document.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=b.dataset.up!=null?i-1:i+1;[draft[i],draft[j]]=[draft[j],draft[i]];persist();render();});}
function fail(text){error=text;render();}
async function refresh(){const selected=config;try{const [data,statusView]=await Promise.all([dispatchCall('status',{},selected.token),dispatchCall('view',{},selected.token)]);if(config?.id!==selected.id)return;statuses=data.packets;driverView=statusView.view?{...await openDispatchView(selected,statusView.view),serverUpdatedAt:statusView.view.updated_at}:null;error='';render();recommendBatch();}catch(e){if(config?.id===selected.id)fail(e.message);}}
async function send(){if(sending)return;sending=true;const kind=$('#send-kind').value;try{if((!packet||packet.operation==='orders')&&!await confirmScheduledDriver()){sending=false;return;}render();if(!packet){packet={...await sealDispatch(config,{version:1,mode:config.mode,kind,orders:draft}),operation:'orders'};persist();}render();await postOutbox();}catch(e){sending=false;fail(e.message);}}
async function postOutbox(){const current=packet;await dispatchCall('send',{id:current.id,iv:current.iv,ciphertext:current.ciphertext,mode:current.mode},config.token);if(!['group','reorder'].includes(current.operation)){const history=readSent();if(!history.some(x=>x.dispatchId===current.id)){draft.forEach((d,i)=>history.push({...d,id:`dispatch-${current.id}-${i}`,dispatchId:current.id,batchId:draftKind==='batch'?'dispatch-'+current.id:null,status:'queued',enteredAt:new Date().toISOString()}));localStorage.setItem('dm-manager-sent-'+config.id,JSON.stringify(history.slice(-200)));}}else{groupPending=true;localStorage.setItem('dm-manager-group-'+config.id,current.id);localStorage.setItem('dm-manager-group-at-'+config.id,String(Date.now()));localStorage.setItem('dm-manager-command-kind-'+config.id,current.operation);selectedSent.clear();}packet=null;draft=[];draftKind='single';persist();error='';sending=false;await refresh();}
function orderForm(index){if(packet)return;const d=draft[index]||{},scheduleDate=d.scheduledAt?new Date(d.scheduledAt):new Date(),savedTime=d.scheduledAt?String(scheduleDate.getHours()).padStart(2,'0')+':'+String(scheduleDate.getMinutes()).padStart(2,'0'):null,suggestedTime=String(Math.floor((Math.ceil((scheduleDate.getHours()*60+scheduleDate.getMinutes())/15)*15%1440)/60)).padStart(2,'0')+':'+String(Math.ceil(scheduleDate.getMinutes()/15)*15%60).padStart(2,'0'),times=Array.from({length:96},(_,i)=>String(Math.floor(i/4)).padStart(2,'0')+':'+String(i%4*15).padStart(2,'0')),modal=document.createElement('dialog');document.body.append(modal);modal.innerHTML=`<form><h2>${index==null?'Add order':'Edit order'}</h2><button id="manager-scan" type="button" class="primary">Scan ticket</button><p class="muted">Scanner setup uses the restaurant’s driver setup code once. Review the result before saving.</p><label>Customer name<input name="name" autocapitalize="words" value="${esc(d.name)}"></label><label>Customer phone<input name="phone" type="tel" inputmode="tel" value="${esc(d.phone)}"></label><label>Delivery address and unit<input name="address" required value="${esc(d.address)}" placeholder="Seattle street address and unit"></label><label>Ticket number<input name="ticket" inputmode="numeric" value="${esc(d.ticket)}"></label><label class="checkbox-label"><input id="manager-cold" name="cold" type="checkbox" ${d.hasColdItems?'checked':''}> Drinks or Ice Cream?</label><div id="manager-cold-details" ${d.hasColdItems?'':'hidden'}><label for="manager-cold-items">Which drinks and ice cream?</label><textarea id="manager-cold-items" name="coldItemDetails" maxlength="500" ${d.hasColdItems?'required':''} placeholder="For example: 2 Thai iced teas, 1 coconut ice cream">${esc(d.coldItemDetails)}</textarea><p class="muted">These items appear in the driver’s delivery confirmation.</p></div><label class="checkbox-label"><input id="manager-alcohol" name="alcohol" type="checkbox" ${d.hasAlcohol?'checked':''}> Alcohol?</label><div id="manager-alcohol-note" class="alcohol-reminder" ${d.hasAlcohol?'':'hidden'}>Bring an alcohol receipt for the customer to sign. The driver must check ID.</div><label class="checkbox-label"><input name="signature" type="checkbox" ${d.needsSignature?'checked':''}> Needs signature (tip / receipt)</label><label class="checkbox-label"><input id="manager-scheduled" name="isScheduled" type="checkbox" ${d.scheduledAt?'checked':''}> Scheduled Delivery?</label><div id="manager-schedule-fields" ${d.scheduledAt?'':'hidden'}><label for="manager-time">Requested delivery time</label><select id="manager-time" name="scheduledTime">${(savedTime&&!times.includes(savedTime)?[savedTime,...times]:times).map(value=>{const [h,m]=value.split(':').map(Number);return `<option value="${value}" ${value===(savedTime||suggestedTime)?'selected':''}>${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}</option>`;}).join('')}</select><p class="muted">${scheduleDate.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} · 15-minute increments</p></div><label>Notes<textarea name="notes">${esc(d.notes)}</textarea></label><p class="error" role="alert"></p><div class="actions"><button id="cancel-order" type="button">Cancel</button><button class="primary">Save order</button></div></form>`;modal.showModal();const field=name=>modal.querySelector(`[name=${name}]`);modal.querySelector('#manager-cold').onchange=e=>{modal.querySelector('#manager-cold-details').hidden=!e.target.checked;field('coldItemDetails').required=e.target.checked;};modal.querySelector('#manager-alcohol').onchange=e=>{modal.querySelector('#manager-alcohol-note').hidden=!e.target.checked;};modal.querySelector('#manager-scheduled').onchange=e=>{modal.querySelector('#manager-schedule-fields').hidden=!e.target.checked;};field('phone').oninput=e=>{e.target.value=formatPhone(e.target.value);};const close=()=>{modal.close();modal.remove();};modal.querySelector('#cancel-order').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.querySelector('#manager-scan').onclick=()=>openTicketScanner(result=>{for(const k of ['name','phone','address','ticket'])if(result.fields?.[k]||result[k])modal.querySelector(`[name=${k}]`).value=result.fields?.[k]||result[k];});modal.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),cold=!!f.get('cold');if(cold&&!f.get('coldItemDetails').trim()){modal.querySelector('.error').textContent='List the drinks or ice cream.';return;}const value={name:f.get('name').trim(),phone:formatPhone(f.get('phone').trim()),address:f.get('address').trim(),ticket:f.get('ticket').trim(),hasColdItems:cold,coldItemDetails:cold?f.get('coldItemDetails').trim():'',hasAlcohol:!!f.get('alcohol'),needsSignature:!!f.get('signature'),notes:f.get('notes').trim(),scheduledAt:f.get('isScheduled')?scheduledInstant(scheduleDate.toISOString(),f.get('scheduledTime')):null};if(index==null)draft.push(value);else draft[index]=value;persist();close();render();};}
render();

function bindDriverChoice(){const select=$('#dispatch-driver');if(select)select.onchange=()=>{if(sending||draft.length||packet){select.value=config?.id||'';return;}const chosen=drivers.find(c=>c.id===select.value);if(!chosen)return;config=chosen;localStorage.setItem(key,JSON.stringify(chosen));draft=JSON.parse(localStorage.getItem('dm-manager-draft-'+chosen.id)||'[]');packet=JSON.parse(localStorage.getItem('dm-manager-outbox-'+chosen.id)||'null');draftKind=localStorage.getItem('dm-manager-kind-'+chosen.id)||'single';statuses=[];driverView=null;selectedSent.clear();groupPending=false;error='';render();};if($('#rename-driver'))$('#rename-driver').onclick=()=>{const modal=document.createElement('dialog');modal.innerHTML=`<form><h2>Driver name</h2><label for="saved-driver-name">Name</label><input id="saved-driver-name" required maxlength="40" value="${esc(config.driverName||'')}"><div class="actions"><button type="button">Cancel</button><button class="primary">Save name</button></div></form>`;document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('[type=button]').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});modal.querySelector('form').onsubmit=e=>{e.preventDefault();config=rememberManagerDriver(localStorage,config,modal.querySelector('input').value);drivers=savedManagerDrivers(localStorage);close();render();};};}

function readSent(){try{return JSON.parse(localStorage.getItem('dm-manager-sent-'+config.id)||'[]');}catch{return [];}}
function visibleSent(){if(!config)return [];const map=new Map(readSent().map(d=>[d.id,d]));for(const d of driverView?.orders||[])map.set(d.id,{...map.get(d.id),...d});return [...map.values()].map(d=>{const receipt=statuses.find(p=>p.id===d.dispatchId);return d.status==='queued'&&receipt?.status==='expired'?{...d,status:'expired'}:d.status==='queued'&&receipt?.status==='received'?{...d,status:'received — awaiting status'}:d;}).sort((a,b)=>{const rank=d=>d.status==='active'?0:['delivered','canceled','expired'].includes(d.status)?2:1;return rank(a)-rank(b)||Date.parse(b.enteredAt)-Date.parse(a.enteredAt);});}
function eligibleSent(d){return !d.batchId&&['queued','pending','ready'].includes(d.status)&&!d.departedAt;}
function sentOrderView(){if(!config)return '';const orders=visibleSent(),groups=new Map();for(const id of selectedSent)if(!orders.some(d=>d.id===id&&eligibleSent(d)))selectedSent.delete(id);for(const d of orders){const k=d.batchId||d.id;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(d);}const outcomes=driverView?.commands||[];const pendingId=localStorage.getItem('dm-manager-group-'+config.id);groupPending=!!pendingId;if(outcomes.some(x=>x.id===pendingId)||statuses.some(x=>x.id===pendingId&&x.status==='expired')||pendingId&&Date.now()-Number(localStorage.getItem('dm-manager-group-at-'+config.id)||Date.now())>86400000){localStorage.removeItem('dm-manager-group-'+config.id);groupPending=false;}return `<section class="card"><div class="row"><h2>Your dispatched orders</h2><button id="refresh-orders">Refresh orders</button></div><p class="muted">${driverView?`Driver last synced ${new Date(driverView.serverUpdatedAt).toLocaleTimeString()}. Updates arrive while the driver’s app is open and connected.`:'Waiting for the driver to sync. Queued orders are not yet confirmed on the driver’s phone.'}</p>${!driverView?.capabilities?.batchRequests?'<p class="muted">Open the updated driver app to enable batch recommendations.</p>':''}${driverView?.omitted?`<p class="muted">${driverView.omitted} older orders are outside the current shared view.</p>`:''}${['group','reorder'].includes(packet?.operation)||groupPending?`<p class="hint">${localStorage.getItem('dm-manager-command-kind-'+config.id)==='reorder'||packet?.operation==='reorder'?'Route update':'Batch'} requested. Waiting for the driver’s app to check and apply it.</p>`:''}${outcomes.slice(-3).map(c=>`<p class="${c.outcome==='rejected'?'error':'hint'}">${esc(c.message)}</p>`).join('')}<button id="batch-selected" class="primary" ${!driverView?.capabilities?.batchRequests||selectedSent.size<2||groupPending||sending||packet||draft.length?'disabled':''}>Create batch from selected (${selectedSent.size})</button>${[...groups.values()].map(group=>{if(group[0].batchId)group.sort((a,b)=>(a.batchPosition??0)-(b.batchPosition??0));const d=group[0],done=group.every(x=>['delivered','canceled','expired'].includes(x.status)),color=group.every(x=>x.dispatchColor===d.dispatchColor&&(x.dispatchGroupId||x.dispatchId)===(d.dispatchGroupId||d.dispatchId))?d.dispatchColor||'':'';return `<details data-sent-group="${esc(d.batchId||d.id)}" class="card ${color?'dispatch-order dispatch-'+esc(color):''}" ${(sentExpanded.get(d.batchId||d.id)??!done)?'open':''}><summary><strong>${d.batchId?esc(d.batchLabel||'Batch')+' · '+group.length+' orders':esc(d.name||'Delivery')}</strong> · ${esc(group.every(x=>x.status==='delivered')?'Delivered':group.length>1?(group.every(x=>x.status===d.status)?d.status:'In progress'):d.status)}</summary><div class="batch-route-actions">${d.batchId?`<button type="button" data-customize-sent-route="${esc(d.batchId)}" class="primary" ${!driverView?.capabilities?.routeRequests||!group.every(x=>['pending','ready','queued'].includes(x.status)&&!x.departedAt)||packet||groupPending||sending||draft.length?'disabled':''}>Customize route</button>`:''}<button type="button" data-view-sent-route="${esc(d.batchId||d.id)}">View route</button></div>${group.map(x=>`<div class="manager-stop sent-order-stop"><div>${eligibleSent(x)?`<label class="checkbox-label"><input type="checkbox" data-sent-select="${esc(x.id)}" ${selectedSent.has(x.id)?'checked':''}> Select for batch</label>`:''}<strong>${esc(x.name||'Delivery')} ${x.ticket?'· #'+esc(x.ticket):''}</strong><p>${esc(x.address)}</p>${x.phone?`<small>Phone: ${esc(x.phone)}</small>`:''}<span class="badge">${esc(x.status)}</span>${x.dispatchAddition?`<span class="badge dispatch-label dispatch-${esc(x.dispatchColor)}">Addition ${x.dispatchAddition}</span>`:''}${x.scheduledAt?`<p>Scheduled ${new Date(x.scheduledAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</p>`:''}${x.hasColdItems?`<p>Drinks / ice cream: ${esc(x.coldItemDetails)}</p>`:''}${x.hasAlcohol?'<span class="badge signature-tag">Check ID · Needs signature</span>':''}${x.notes?`<p>Notes: ${esc(x.notes)}</p>`:''}${x.completedAt?`<small>Delivered ${new Date(x.completedAt).toLocaleTimeString()}</small>`:''}</div></div>`).join('')}</details>`;}).join('')||'<p>No orders sent yet.</p>'}</section>`;}
function bindSentOrders(){if($('#refresh-orders'))$('#refresh-orders').onclick=refresh;if($('#batch-selected'))$('#batch-selected').onclick=()=>requestBatch([...selectedSent]);document.querySelectorAll('[data-sent-select]').forEach(c=>c.onchange=()=>{c.checked?selectedSent.add(c.dataset.sentSelect):selectedSent.delete(c.dataset.sentSelect);render();});}
async function requestBatch(ids){if(!driverView?.capabilities?.batchRequests)return fail('Open the updated driver app before requesting a batch.');if(groupPending)return fail('Wait for the current batch request to be checked by the driver.');if(sending||packet||draft.length)return fail('Finish the current addition first.');if(ids.length<2||ids.length>12)return fail('Select two to twelve unstarted single orders.');sending=true;try{packet={...await sealDispatch(config,{version:1,action:'group',mode:config.mode,deliveryIds:ids}),operation:'group'};persist();render();await postOutbox();}catch(e){sending=false;fail(e.message);}}
function recommendBatch(){if(!driverView?.capabilities?.batchRequests)return;if(!config||groupPending||packet||draft.length||document.querySelector('dialog[open]'))return;const candidates=visibleSent().filter(eligibleSent).sort((a,b)=>Date.parse(a.enteredAt)-Date.parse(b.enteredAt)).slice(0,12);if(candidates.length<2)return;const signature=config.id+'/'+candidates.map(d=>d.id).sort().join('/');if(dismissedRecommendations.has(signature))return;dismissedRecommendations.add(signature);const modal=document.createElement('dialog');modal.innerHTML=`<h2>Take these orders together?</h2><p>${candidates.length} single orders are waiting for this driver. Create one batch?</p><p class="muted">Based on the latest received status. The driver’s app will refuse the change if either delivery has started.</p><div class="actions"><button id="keep-single">Keep singles</button><button id="combine-singles" class="primary">Create batch</button></div>`;document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('#keep-single').onclick=close;modal.querySelector('#combine-singles').onclick=()=>{close();requestBatch(candidates.map(d=>d.id));};modal.addEventListener('cancel',e=>{e.preventDefault();close();});}
setInterval(()=>{if(config&&!sending&&!document.hidden&&!document.querySelector('dialog[open]')&&!$('#pair-form'))refresh();},15000);
if(config)refresh();

function mapsSettings(){return {mapsProvider:localStorage.getItem('dm-manager-maps')||(/Android/i.test(navigator.userAgent)?'google':'apple')};}
function draftRouteStops(){return draft.map((d,i)=>({...d,id:'draft-'+i,_draftIndex:i,status:'ready',enteredAt:d.enteredAt||new Date().toISOString()}));}
function bindManagerRoutes(){if($('#customize-draft-route'))$('#customize-draft-route').onclick=()=>customizeManagerRoute(draftRouteStops(),null);if($('#view-draft-route'))$('#view-draft-route').onclick=()=>viewManagerRoute(draftRouteStops());document.querySelectorAll('[data-customize-sent-route]').forEach(b=>b.onclick=()=>customizeManagerRoute(visibleSent().filter(d=>d.batchId===b.dataset.customizeSentRoute).sort((a,b)=>(a.batchPosition??0)-(b.batchPosition??0)),b.dataset.customizeSentRoute));document.querySelectorAll('[data-view-sent-route]').forEach(b=>b.onclick=()=>{const stops=visibleSent().filter(d=>(d.batchId||d.id)===b.dataset.viewSentRoute).sort((a,b)=>(a.batchPosition??0)-(b.batchPosition??0)),remaining=stops.filter(d=>!['delivered','canceled','expired'].includes(d.status));viewManagerRoute(remaining.length?remaining:stops);});}
function viewManagerRoute(stops){if(!stops.length)return;const modal=document.createElement('dialog');modal.innerHTML=`<h2>View route</h2><ol class="route-addresses">${stops.map(d=>`<li><strong>${esc(d.name||'Delivery')}</strong><div>${esc(navigationAddress(d.address))}</div>${d.scheduledAt?'<span class="badge scheduled">Scheduled</span>':''}</li>`).join('')}</ol><label for="manager-maps-choice">Maps app</label><select id="manager-maps-choice"><option value="apple">Apple Maps</option><option value="google">Google Maps</option></select><div id="manager-map-links"></div><p class="muted">Opening Maps previews this order of stops. It does not start the driver’s run or change a route already open on their phone. The route ends at the last delivery.</p><button type="button" id="close-map-preview">Done</button>`;document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('#close-map-preview').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});const select=modal.querySelector('select');select.value=mapsSettings().mapsProvider;const draw=()=>{localStorage.setItem('dm-manager-maps',select.value);const settings=mapsSettings(),chunks=[];for(let i=0;i<stops.length;i+=settings.mapsProvider==='google'?4:stops.length)chunks.push(stops.slice(i,i+(settings.mapsProvider==='google'?4:stops.length)));modal.querySelector('#manager-map-links').innerHTML=(chunks.length>1?'<p class="hint">Google Maps opens up to four stops per link. Open each section in order.</p>':'')+chunks.map((chunk,i)=>`<a class="button-link primary" target="_blank" rel="noopener" href="${esc(directionsURL(chunk.map(d=>d.address),settings,navigationAddress))}">Open ${chunks.length>1?'route section '+(i+1):'directions'} in ${providerName(settings)}</a>`).join('');};select.onchange=draw;draw();}
function customizeManagerRoute(initial,batchId){if(!batchId&&(packet||sending))return fail('Finish the current send before changing its route.');if(!initial.length)return;let stops=[...initial];const modal=document.createElement('dialog');modal.innerHTML=`<h2>Customize route</h2><p>Due-soon and prioritized scheduled orders lead; route suggestions then use ticket numbers and nearby stops.</p><button type="button" class="primary" id="manager-suggest-route">Suggest route order</button><p class="muted" id="manager-route-location">Uses downloaded Seattle address points on this device. Straight-line distances, not traffic or driving-time estimates.</p><div id="manager-route-stops"></div><div class="actions"><button id="manager-route-cancel" type="button">Cancel</button><button id="manager-route-save" type="button" class="primary">${batchId?'Send route order to driver':'Save stop order'}</button></div><p class="error" role="alert"></p>`;document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.querySelector('#manager-route-cancel').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close();});const draw=()=>{modal.querySelector('#manager-route-stops').innerHTML=stops.map((d,i)=>`<div class="card"><div class="row"><strong>${i+1}. ${esc(d.name||'Delivery')}</strong>${d.scheduledAt?'<span class="badge scheduled">Scheduled</span>':''}</div><p>${esc(navigationAddress(d.address))}</p><small>${d.ticket?'Ticket '+esc(d.ticket)+' · ':''}${locationFor(d.address)?'Location matched':locationStatus().ready?'Exact location not matched':'Location not checked yet'}</small><div class="actions"><button type="button" data-manager-up="${i}" aria-label="Move stop ${i+1} up" ${i===0?'disabled':''}>↑</button><button type="button" data-manager-down="${i}" aria-label="Move stop ${i+1} down" ${i===stops.length-1?'disabled':''}>↓</button><button type="button" data-manager-preview="${i}">Preview address</button></div></div>`).join('');modal.querySelectorAll('[data-manager-up],[data-manager-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.managerUp??b.dataset.managerDown),j=b.dataset.managerUp!=null?i-1:i+1;[stops[i],stops[j]]=[stops[j],stops[i]];draw();});modal.querySelectorAll('[data-manager-preview]').forEach(b=>b.onclick=()=>viewManagerRoute([stops[Number(b.dataset.managerPreview)]]));};modal.querySelector('#manager-suggest-route').onclick=async()=>{const suggest=modal.querySelector('#manager-suggest-route'),save=modal.querySelector('#manager-route-save');suggest.disabled=true;save.disabled=true;modal.querySelector('#manager-route-location').textContent='Checking local address locations…';try{await loadLocations();const result=suggestedOrder(stops);stops=result.stops;draw();modal.querySelector('#manager-route-location').textContent=result.unlocated.length?`${result.unlocated.length} addresses could not be matched exactly. Scheduled/ticket priorities still apply; check the route in Maps.`:'Suggested order applied. Review it before saving.';}catch{const result=suggestedOrder(stops);stops=result.stops;draw();modal.querySelector('#manager-route-location').textContent='Address locations unavailable. Scheduled and ticket priorities applied; geographic suggestions need the local download.';}finally{suggest.disabled=false;save.disabled=false;}};modal.querySelector('#manager-route-save').onclick=async()=>{if(batchId){try{await requestRouteOrder(batchId,stops.map(d=>d.id));close();}catch(e){modal.querySelector('.error').textContent=e.message;}}else{draft=stops.map(d=>({...draft[d._draftIndex],routeCustomized:true}));persist();close();render();}};draw();}
async function requestRouteOrder(batchId,ids){if(!driverView?.capabilities?.routeRequests)throw Error('Open the updated driver app to enable route changes.');if(sending||packet||draft.length||groupPending)throw Error('Finish the current addition or request first.');sending=true;try{packet={...await sealDispatch(config,{version:1,action:'reorder',mode:config.mode,batchId,deliveryIds:ids}),operation:'reorder'};persist();render();await postOutbox();}catch(e){sending=false;fail(e.message);throw e;}}

function confirmScheduledDriver(){
 const check=driverScheduleCheck(config?.driverName);
 if(!check.mismatch)return Promise.resolve(true);
 return new Promise(resolve=>{
 const modal=document.createElement('dialog');modal.setAttribute('aria-labelledby','driver-schedule-title');
 modal.innerHTML=`<h2 id="driver-schedule-title">Is this the right driver?</h2><p><strong>${check.usual} usually works ${check.day} nights.</strong></p><p>This addition is addressed to <strong>${esc(config.driverName||'the selected driver')}</strong>. Is that who’s covering tonight?</p><p class="muted">Nothing has been sent. Go back to review, or confirm a coverage shift.</p><div class="actions"><button type="button" id="schedule-back">Go back</button><button type="button" class="primary" id="schedule-confirm">Yes, send to ${esc(config.driverName||'this driver')}</button></div>`;
 document.body.append(modal);const finish=value=>{modal.close();modal.remove();resolve(value);};
 modal.querySelector('#schedule-back').onclick=()=>finish(false);modal.querySelector('#schedule-confirm').onclick=()=>finish(true);
 modal.addEventListener('cancel',e=>{e.preventDefault();finish(false);});modal.showModal();modal.querySelector('#schedule-back').focus();
 });
}

function scheduleHint(){const check=driverScheduleCheck(config?.driverName);return check.usual?`<p class="hint"><strong>${check.usual} usually works ${check.day} nights.</strong>${check.mismatch?' Check the selected driver before building an addition.':''}</p>`:'';}
